-- Baseline schema (versión PostgreSQL). Puerto 1:1 del init_db() de la app
-- Flask original / la versión SQLite, con la sintaxis adaptada a Postgres:
-- AUTOINCREMENT -> GENERATED BY DEFAULT AS IDENTITY, datetime('now','localtime')
-- -> to_char(now(), ...) (se mantiene el tipo TEXT para no romper el resto
-- del código, que trata las fechas como cadenas "YYYY-MM-DD[ HH:MM:SS]").
-- Todos los CREATE ... IF NOT EXISTS son no-ops sobre una BBDD existente.

CREATE TABLE IF NOT EXISTS pacientes (
    id               INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre           TEXT NOT NULL,
    fecha_nac        TEXT,
    sexo             TEXT,
    dni              TEXT,
    telefono         TEXT,
    email            TEXT,
    objetivo         TEXT,
    actividad_fisica TEXT,
    intolerancias    TEXT,
    patologias       TEXT,
    notas            TEXT,
    peso             DOUBLE PRECISION,
    talla            DOUBLE PRECISION,
    grupo_sanguineo  TEXT,
    creado           TEXT DEFAULT (to_char(now(), 'YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS revisiones (
    id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    paciente_id     INTEGER NOT NULL,
    fecha           TEXT DEFAULT (to_char(now(), 'YYYY-MM-DD')),
    peso            DOUBLE PRECISION,
    talla           DOUBLE PRECISION,
    envergadura     DOUBLE PRECISION,
    pl_bicipital    DOUBLE PRECISION,
    pl_tricipital   DOUBLE PRECISION,
    pl_subescapular DOUBLE PRECISION,
    pl_supraespinal DOUBLE PRECISION,
    pl_supracrestal DOUBLE PRECISION,
    pl_abdominal    DOUBLE PRECISION,
    pl_muslo_int    DOUBLE PRECISION,
    pl_pierna_med   DOUBLE PRECISION,
    per_antebrazo   DOUBLE PRECISION,
    per_brazo_rel   DOUBLE PRECISION,
    per_brazo_cont  DOUBLE PRECISION,
    per_hombros     DOUBLE PRECISION,
    per_pecho       DOUBLE PRECISION,
    per_cintura     DOUBLE PRECISION,
    per_caderas     DOUBLE PRECISION,
    per_muslo       DOUBLE PRECISION,
    per_muslo_cont  DOUBLE PRECISION,
    per_gemelo      DOUBLE PRECISION,
    notas           TEXT,
    FOREIGN KEY (paciente_id) REFERENCES pacientes(id)
);

CREATE TABLE IF NOT EXISTS fotos (
    id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    paciente_id INTEGER NOT NULL,
    filename    TEXT NOT NULL,
    nota        TEXT,
    fecha       TEXT DEFAULT (to_char(now(), 'YYYY-MM-DD HH24:MI:SS')),
    FOREIGN KEY (paciente_id) REFERENCES pacientes(id)
);

CREATE TABLE IF NOT EXISTS stock_categorias (
    id     INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS stock_proveedores (
    id       INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre   TEXT NOT NULL,
    telefono TEXT,
    email    TEXT,
    notas    TEXT
);

CREATE TABLE IF NOT EXISTS stock_productos (
    id           INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre       TEXT NOT NULL,
    categoria_id INTEGER,
    proveedor_id INTEGER,
    precio_coste DOUBLE PRECISION DEFAULT 0,
    precio_venta DOUBLE PRECISION DEFAULT 0,
    unidad       TEXT DEFAULT 'ud',
    stock_minimo DOUBLE PRECISION DEFAULT 0,
    activo       INTEGER DEFAULT 1,
    creado       TEXT DEFAULT (to_char(now(), 'YYYY-MM-DD HH24:MI:SS')),
    FOREIGN KEY (categoria_id) REFERENCES stock_categorias(id),
    FOREIGN KEY (proveedor_id) REFERENCES stock_proveedores(id)
);

CREATE TABLE IF NOT EXISTS stock_compras (
    id           INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fecha        TEXT DEFAULT (to_char(now(), 'YYYY-MM-DD')),
    proveedor_id INTEGER,
    notas        TEXT,
    total        DOUBLE PRECISION DEFAULT 0,
    FOREIGN KEY (proveedor_id) REFERENCES stock_proveedores(id)
);

CREATE TABLE IF NOT EXISTS stock_compras_lineas (
    id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    compra_id       INTEGER NOT NULL,
    producto_id     INTEGER NOT NULL,
    cantidad        DOUBLE PRECISION NOT NULL,
    precio_unitario DOUBLE PRECISION DEFAULT 0,
    FOREIGN KEY (compra_id)   REFERENCES stock_compras(id),
    FOREIGN KEY (producto_id) REFERENCES stock_productos(id)
);

CREATE TABLE IF NOT EXISTS stock_ventas (
    id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fecha       TEXT DEFAULT (to_char(now(), 'YYYY-MM-DD')),
    paciente_id INTEGER,
    notas       TEXT,
    total       DOUBLE PRECISION DEFAULT 0,
    FOREIGN KEY (paciente_id) REFERENCES pacientes(id)
);

CREATE TABLE IF NOT EXISTS stock_ventas_lineas (
    id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    venta_id        INTEGER NOT NULL,
    producto_id     INTEGER NOT NULL,
    cantidad        DOUBLE PRECISION NOT NULL,
    precio_unitario DOUBLE PRECISION DEFAULT 0,
    FOREIGN KEY (venta_id)    REFERENCES stock_ventas(id),
    FOREIGN KEY (producto_id) REFERENCES stock_productos(id)
);
